import { readFileSync } from 'node:fs'
import { resolveRecord, normalizeRecord, Failure } from './uri.js'

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'normalize' && mode !== 'resolve') {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
try {
  lines.forEach((line, i) => {
    try {
      out.push(mode === 'normalize' ? normalizeRecord(line) : resolveRecord(line))
    } catch (e) {
      if (e instanceof Failure) throw new Failure(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof Failure)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
EOF
cat > src/uri.js <<'EOF'
export class Failure extends Error {}

export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    m = /^\/\/([^/?#]*)/.exec(s)
    r.authority = m[1]
    s = s.slice(m[0].length)
  }
  m = /^[^?#]*/.exec(s)
  r.path = m[0]
  s = s.slice(m[0].length)
  if (s.startsWith('?')) {
    m = /^\?([^#]*)/.exec(s)
    r.query = m[1]
    s = s.slice(m[0].length)
  }
  if (s.startsWith('#')) r.fragment = s.slice(1)
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const from = hp.lastIndexOf(']') + 1
  const c = hp.indexOf(':', from)
  return c >= 0
    ? { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) }
    : { userinfo, host: hp, port: undefined }
}

const bad = /%(?![0-9A-Fa-f]{2})/
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRESERVED = /^[A-Za-z0-9\-._~]$/
const pct = (s) =>
  s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })

export function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const m = /^\/?[^/]*/.exec(inp)
      out.push(m[0])
      inp = inp.slice(m[0].length)
    }
  }
  return out.join('')
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function normalize(r) {
  const auth = r.authority === undefined ? undefined : splitAuthority(r.authority)
  const checks = [
    ['path', r.path],
    ['userinfo', auth?.userinfo],
    ['host', auth?.host],
    ['query', r.query],
    ['fragment', r.fragment],
  ]
  for (const [name, v] of checks) {
    if (v !== undefined && bad.test(v)) throw new Failure(`the ${name} has a truncated percent-encoding`)
  }
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let path = removeDots(pct(r.path))
  let a
  if (auth) {
    let port = auth.port
    if (port === '' || (port !== undefined && port === DEFAULT_PORTS[scheme])) port = undefined
    a = (auth.userinfo === undefined ? '' : pct(auth.userinfo) + '@') + lower(pct(auth.host)) +
      (port === undefined ? '' : ':' + port)
    if (path === '') path = '/'
  }
  let s = ''
  if (scheme !== undefined) s += scheme + ':'
  if (a !== undefined) s += '//' + a
  s += path
  if (r.query !== undefined) s += '?' + pct(r.query)
  if (r.fragment !== undefined) s += '#' + pct(r.fragment)
  return s
}

export function normalizeRecord(line) {
  return normalize(parse(line))
}

export function resolveRecord(line) {
  const sp = line.indexOf(' ')
  if (sp < 0) throw new Failure('expected a base and a reference')
  const base = parse(line.slice(0, sp))
  if (base.scheme === undefined) throw new Failure('the base has no scheme')
  const ref = parse(line.slice(sp + 1))
  let t
  if (ref.scheme !== undefined) {
    t = { ...ref, path: removeDots(ref.path) }
  } else if (ref.authority !== undefined) {
    t = { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  } else if (ref.path === '') {
    t = { scheme: base.scheme, authority: base.authority, path: base.path,
      query: ref.query !== undefined ? ref.query : base.query, fragment: ref.fragment }
  } else {
    let path = ref.path
    if (!path.startsWith('/')) {
      if (base.authority !== undefined && base.path === '') path = '/' + path
      else {
        const i = base.path.lastIndexOf('/')
        path = (i >= 0 ? base.path.slice(0, i + 1) : '') + path
      }
    }
    t = { scheme: base.scheme, authority: base.authority, path: removeDots(path),
      query: ref.query, fragment: ref.fragment }
  }
  return normalize(t)
}
EOF
