const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'replay' && mode[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parseInt_(s, field, least) {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function makeBucket(name, cap, refill, per) {
  return {
    name,
    fresh() { return { num: cap * per, last: null } },
    advance(st, t) {
      if (st.last !== null && t > st.last) {
        st.num += refill * (t - st.last)
        if (st.num > cap * per) st.num = cap * per
      }
      st.last = t
    },
    allows(st) { return st.num >= per },
    record(st) { st.num -= per },
  }
}

function makeWindow(name, limit, span) {
  return {
    name,
    fresh() { return { ticks: [] } },
    advance(st, t) {
      const cut = t - span
      st.ticks = st.ticks.filter((x) => x > cut)
    },
    allows(st) { return BigInt(st.ticks.length) < limit },
    record(st, t) { st.ticks.push(t) },
  }
}

function run(text) {
  const policies = new Map()
  const routes = new Map()
  const states = new Map() // key -> Map(policy -> state)
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0
  let lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (w.length !== n) throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        let p
        if (d === 'bucket') {
          const cap = parseInt_(w[2], 'capacity', 1)
          const refill = parseInt_(w[3], 'refill', 0)
          const per = parseInt_(w[4], 'per', 1)
          if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
          p = makeBucket(w[1], cap, refill, per)
        } else {
          const limit = parseInt_(w[2], 'limit', 0)
          const span = parseInt_(w[3], 'span', 1)
          if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
          p = makeWindow(w[1], limit, span)
        }
        policies.set(w[1], p)
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        const list = []
        for (const n of w.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(w[1], list)
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const t = parseInt_(w[1], 'tick', 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (prev !== null && t < prev) throw new Fail(`tick ${t} is before tick ${prev}`)
        started = true
        prev = t
        const key = w[2]
        let best = null
        for (const [pre, list] of routes) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let refused = null
        if (best !== null) {
          const list = routes.get(best)
          let km = states.get(key)
          if (!km) states.set(key, (km = new Map()))
          const sts = list.map((p) => {
            let s = km.get(p)
            if (!s) km.set(p, (s = p.fresh()))
            return s
          })
          list.forEach((p, j) => p.advance(sts[j], t))
          for (let j = 0; j < list.length; j++) {
            if (!list[j].allows(sts[j])) { refused = list[j]; break }
          }
          if (!refused) list.forEach((p, j) => p.record(sts[j], t))
        }
        let s = stats.get(key)
        if (!s) stats.set(key, (s = { a: 0, d: 0 }))
        if (refused) { s.d++; denied++ } else { s.a++; allowed++ }
        out.push(`${w[1]} ${key} ${refused ? 'deny ' + refused.name : 'allow'}`)
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  if (mode[0] === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') +
    `total allowed=${allowed} denied=${denied}\n`
}

import { readFileSync } from 'node:fs'
let input = readFileSync(0, 'utf8')
try {
  process.stdout.write(run(input))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
