  const input = 'bucket wide 5 0 1\nbucket tight 1 0 1\nroute a wide\nroute ab tight\nevent 0 abc\nevent 0 abc\n'
  assert.equal(run(['replay'], input).out, '0 abc allow\n0 abc deny tight\n')
