cat > src/parse.js <<'EOF'
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}
const fail = (reason) => { throw new Fail(reason) }

function int(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
  return BigInt(text)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      if (!['bucket', 'window', 'route', 'event'].includes(d)) fail(`unknown directive ${d}`)
      if (d !== 'event' && events.length > 0) fail('declarations must come before the first event')
      if (d === 'bucket') {
        if (w.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(w[1])) fail(`invalid policy name ${w[1]}`)
        const capacity = int('capacity', w[2], 1)
        const refill = int('refill', w[3], 0)
        const per = int('per', w[4], 1)
        if (policies.has(w[1])) fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { kind: 'bucket', name: w[1], capacity, refill, per })
      } else if (d === 'window') {
        if (w.length !== 4) fail('expected window <name> <limit> <span>')
        if (!NAME.test(w[1])) fail(`invalid policy name ${w[1]}`)
        const limit = int('limit', w[2], 0)
        const span = int('span', w[3], 1)
        if (policies.has(w[1])) fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { kind: 'window', name: w[1], limit, span })
      } else if (d === 'route') {
        if (w.length < 3) fail('expected route <prefix> <policy>...')
        if (!NAME.test(w[1])) fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) fail(`prefix ${w[1]} is routed twice`)
        const list = w.slice(2).map((n) => policies.get(n) ?? fail(`unknown policy ${n}`))
        routes.set(w[1], list)
      } else {
        if (w.length !== 3) fail('expected event <tick> <key>')
        const tick = int('tick', w[1], 0)
        if (!NAME.test(w[2])) fail(`invalid key ${w[2]}`)
        if (last !== null && tick < last) fail(`tick ${tick} is before tick ${last}`)
        last = tick
        events.push({ tick, key: w[2] })
      }
    } catch (e) {
      if (e instanceof Fail) return { error: { line: i + 1, reason: e.message } }
      throw e
    }
  }
  return { routes, events }
}
