const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])

export function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--)
    L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ts = 0
  const flush = () => {
    if (i > bs || j > ts) out.push({ bs, be: i, ts, te: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush(); i++; j++; bs = i; ts = j
    } else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return out
}

export function merge(mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const regions = []
  let pos = 0, k = 0
  const stable = to => { if (to > pos) regions.push({ kind: 'stable', lines: base.slice(pos, to) }) }
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) { re = Math.max(re, all[k].be); group.push(all[k++]) }
    stable(rs)
    pos = re
    if (group.length === 1) {
      const c = group[0]
      const src = c.side === 0 ? mine : theirs
      regions.push({ kind: c.side === 0 ? 'mine' : 'theirs', lines: src.slice(c.ts, c.te) })
      continue
    }
    const baseLines = base.slice(rs, re)
    const rep = side => {
      const cs = group.filter(c => c.side === side)
      if (!cs.length) return baseLines
      const src = side === 0 ? mine : theirs
      const minB = Math.min(...cs.map(c => c.bs)), maxB = Math.max(...cs.map(c => c.be))
      const minT = Math.min(...cs.map(c => c.ts)), maxT = Math.max(...cs.map(c => c.te))
      return src.slice(minT - (minB - rs), maxT + (re - maxB))
