    const m = rep(0), t = rep(1)
    if (eq(m, t)) regions.push({ kind: 'both', lines: m })
    else if (eq(m, baseLines)) regions.push({ kind: 'theirs', lines: t })
    else if (eq(t, baseLines)) regions.push({ kind: 'mine', lines: m })
    else regions.push({ kind: 'conflict', mine: m, base: baseLines, theirs: t })
  }
  stable(base.length)
  return { regions }
}
