  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cmpStr(a.v, b.v)
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

const memo = new Map()
const stack = new Set()
function cellValue(col, row) {
  const key = keyOf(col, row)
  const cell = cells.get(key)
  if (!cell) return ZERO
  if (memo.has(key)) return memo.get(key)
  if (stack.has(key)) return err('#CYCLE!')
  stack.add(key)
  const v = evalContent(cell.content)
  stack.delete(key)
  memo.set(key, v)
  return v
}
function evalContent(c) {
  if (c[0] === '=') {
    const ast = parseFormula(c.slice(1))
    return ast ? evalNode(ast) : err('#ERR!')
  }
  if (c === '') return ZERO
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
  if (ERRORS.has(c)) return err(c)
  return { t: 's', v: c }
}

function rangeCells(node) {
  const a = parseAddr(node.a), b = parseAddr(node.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push([c, r])
  return out
}

function evalNode(n) {
  switch (n.k) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'paren': return evalNode(n.e)
    case 'ref': {
      const a = parseAddr(n.a)
      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.t === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (l.t === 'e') return l
      const r = evalNode(n.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (r.t === 'e') return r
        const d = compare(l, r)
        switch (n.op) {
          case '=': return bool(d === 0)
          case '<>': return bool(d !== 0)
          case '<': return bool(d < 0)
          case '<=': return bool(d <= 0)
          case '>': return bool(d > 0)
          default: return bool(d >= 0)
        }
      }
      const x = toNum(l)
      if (x.t === 'e') return x
      const y = toNum(r)
      if (y.t === 'e') return y
      switch (n.op) {
        case '+': return checkFinite(x.v + y.v)
        case '-': return checkFinite(x.v - y.v)
        case '*': return checkFinite(x.v * y.v)
        case '/': return y.v === 0 ? err('#DIV/0!') : checkFinite(x.v / y.v)
        default: return checkFinite(Math.pow(x.v, y.v))
      }
    }
    case 'call': return evalCall(n)
  }
}

const FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])
function evalCall(n) {
  if (!FUNCS.has(n.name)) return err('#NAME?')
  if (n.name === 'IF') {
    if (n.args.length !== 3) return err('#ERR!')
    const cond = evalNode(n.args[0])
    if (cond.t === 'e') return cond
    let truth
    if (cond.t === 'b') truth = cond.v
    else if (cond.t === 'n') truth = cond.v !== 0
    else return err('#VALUE!')
    return evalNode(n.args[truth ? 1 : 2])
  }
  if (n.name === 'ABS') {
    if (n.args.length !== 1) return err('#ERR!')
    const v = toNum(evalNode(n.args[0]))
    return v.t === 'e' ? v : num(Math.abs(v.v))
  }
  if (n.args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of n.args) {
    if (a.k === 'range') {
      const cs = rangeCells(a)
      if (!cs) { vals.push(err('#REF!')); continue }
      for (const [c, r] of cs) vals.push(cellValue(c, r))
    } else vals.push(evalNode(a))
  }
  for (const v of vals) if (v.t === 'e') return v
  if (n.name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (n.name) {
    case 'SUM': return checkFinite(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(nums.reduce((a, b) => Math.min(a, b)))
    case 'MAX': return num(nums.reduce((a, b) => Math.max(a, b)))
    default: return checkFinite(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

// ---- deps
function collectDeps(n, set) {
  switch (n.k) {
    case 'ref': { const a = parseAddr(n.a); if (a) set.set(keyOf(a.col, a.row), a); break }
    case 'range': {
      const cs = rangeCells(n)
      if (cs) for (const [col, row] of cs) set.set(keyOf(col, row), { col, row })
      break
    }
    case 'paren': case 'un': collectDeps(n.e, set); break
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
  }
}

// ---- output
const out = []
for (const cell of sorted) {
  if (mode === 'values') {
    const v = cellValue(cell.col, cell.row)
    let s
    if (v.t === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.t === 'e') s = v.v
    else if (v.t === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${cell.key}=${s}`)
  } else {
    let line = cell.key + ':'
    if (cell.content[0] === '=') {
      const ast = parseFormula(cell.content.slice(1))
      if (ast) {
        const set = new Map()
        collectDeps(ast, set)
        const list = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
        for (const d of list) line += ' ' + keyOf(d.col, d.row)
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

