const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'rounds' && mode[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

import('node:fs').then(({ readFileSync }) => main(readFileSync(0, 'utf8')))

function main(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const ballots = []
  const nameRe = /^[A-Za-z0-9_-]+$/
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const err = (m) => fail(`error: line ${n}: ${m}`)
    if (t[0] === 'candidates') {
      if (cands !== null || ballots.length > 0) err('candidates must be declared once, before any ballot')
      if (t.length < 2) err('expected candidates <name>...')
      cands = []
      for (const name of t.slice(1)) {
        if (!nameRe.test(name)) err(`invalid candidate name ${name}`)
        if (cands.includes(name)) err(`candidate ${name} is declared twice`)
        cands.push(name)
      }
    } else if (t[0] === 'ballot') {
      if (cands === null) err('candidates must be declared once, before any ballot')
      if (t.length < 3) err('expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) err('count must be a positive integer')
      const seen = []
      for (const name of t.slice(2)) {
        if (!cands.includes(name)) err(`unknown candidate ${name}`)
        if (seen.includes(name)) err(`candidate ${name} is repeated`)
        seen.push(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: seen })
    } else err(`unknown directive ${t[0]}`)
  }
  if (cands === null) fail('error: no candidates')

  const total = ballots.reduce((s, b) => s + b.count, 0n)
  const continuing = new Set(cands)
  const history = []
  const out = []
  let winner = null
  for (;;) {
    const counts = new Map(cands.filter((c) => continuing.has(c)).map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
    }
    history.push(counts)
    const listed = [...counts.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
    let line = `round ${history.length}: ` + listed.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
    out.push(line)
    if (active === 0n) break
    const top = listed.find(([, v]) => v * 2n > active)
    if (top) { winner = top[0]; break }
    let min = listed[listed.length - 1][1]
    let s = listed.filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; r < history.length && s.length > 1; r++) {
      const m = s.reduce((a, c) => (history[r].get(c) < a ? history[r].get(c) : a), history[r].get(s[0]))
      s = s.filter((c) => history[r].get(c) === m)
    }
    const el = s.reduce((a, c) => (c > a ? c : a))
    continuing.delete(el)
    out.push(`eliminated ${el}`)
  }
  const end = winner === null ? 'no winner' : `winner ${winner}`
  if (mode[0] === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
  else process.stdout.write(`rounds ${history.length}\n${end}\n`)
}
EOF
