import { readFileSync } from 'node:fs'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'err', v: e })
const num = (v) => ({ t: 'num', v })
const ERR = err('#ERR!')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) fail('error: usage: cli.js values|deps')
const mode = argv[0]

// ---- addresses
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + L.charCodeAt(1) - 64
  return { col, row, key: L + row }
}
function colName(c) {
  return c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
}
const keyOf = (col, row) => colName(col) + row

// ---- parse sheet
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map() // key -> {col,row,content}
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^[^ \t]*/.exec(s)
  const word = m[0]
  const rest = s.slice(word.length).replace(/^[ \t]+/, '')
  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { col: a.col, row: a.row, content: rest })
})

// ---- formula parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ k: 'n', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'w', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[-+*\/^=<>(),:])/.exec(s.slice(i)))) { toks.push({ k: 'o', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].k === 'o' && toks[p].v === v
  const bad = new Error('syntax')
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'o' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
