import { readFileSync } from 'node:fs'

const fail = (m) => { process.stderr.write(m + '\n'); process.exit(2) }
const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'rounds' && mode[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
let cands = null
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (cands) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (t[0] === 'ballot') {
    if (!cands) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (!cands) fail('error: no candidates')

const cont = new Set(cands)
const history = []
const out = []
let winner = null
let nr = 0
for (;;) {
  nr++
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
  }
  history.push(counts)
  let total = 0n
  for (const b of ballots) total += b.count
  const list = [...counts.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
  let line = `round ${nr}: ` + list.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const w = list.find(([, v]) => v * 2n > active)
  if (w) { winner = w[0]; break }
  let min = list[list.length - 1][1]
  let S = list.filter(([, v]) => v === min).map(([c]) => c)
  while (S.length > 1) {
    let split = false
    for (const h of history) {
      const vs = S.map((c) => h.get(c))
      const m = vs.reduce((a, b) => (a < b ? a : b))
      if (vs.some((v) => v !== m)) { S = S.filter((c) => h.get(c) === m); split = true; break }
    }
    if (!split) { S = [S.sort()[S.length - 1]]; }
  }
  out.push(`eliminated ${S[0]}`)
  cont.delete(S[0])
}
const end = winner ? `winner ${winner}` : 'no winner'
if (mode[0] === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${nr}\n${end}\n`)
EOF
