{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { while (k-- > 0) adv() }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      let depth = 0
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advN(2); if (depth === 0) break }
        else adv()
      }
      continue
    }
    const sl = line, sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      push('rawstring', JSON.stringify(v))
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      push(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const take = () => { s += adv() }
      const run = (pred) => {
        while (i < n) {
          if (pred(cs[i])) take()
          else if (cs[i] === '_' && s.length && pred(s[s.length - 1]) && pred(cs[i + 1])) take()
          else break
        }
      }
      const p = cs[i + 1]
      let bad = false
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        take(); take()
        if (!pred(cs[i])) bad = true
        else run(pred)
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1]) || ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2]))) {
            take()
            if (!isDigit(cs[i])) take()
            run(isDigit)
          }
        }
      }
      if (bad || isIdPart(cs[i])) {
        while (i < n && isIdPart(cs[i])) take()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      push('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        if (cs[i] === '\n') throw new ScanError(line, col, 'newline in string')
        const bl = line, bc = col
        const d = adv()
        if (d === '"') break
        if (d !== '\\') { v += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = cs[i]
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e === '\n') throw bad()
        adv()
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw bad()
          v += String.fromCodePoint(parseInt(cs[i] + cs[i + 1], 16))
          advN(2)
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') throw bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) throw bad()
          v += String.fromCodePoint(cp)
          advN(j + 1 - i)
        } else throw bad()
      }
      push('string', JSON.stringify(v))
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    const pu = PUNCT.find((q) => q === two) ?? PUNCT.find((q) => q === c)
    if (pu) {
      advN(pu.length)
      push('punct', pu)
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
let tokens
try {
  tokens = scan(input)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
EOF
