        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        if (cs[i] === '\n') throw new ScanError(line, col, 'newline in string')
        const bl = line, bc = col
        const d = adv()
        if (d === '"') break
        if (d !== '\\') { v += d; continue }
