  fail(USAGE)
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    depUses.push(null)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})
for (const x of depUses) if (x !== null && !cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort()
const dl = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort()]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of dl.get(u)) {
    const s = state.get(v)
    if (s === 1) {
      const cyc = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!s) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.get(k)) dfs(k)

// topological order (deps first)
const order = []
const seen = new Set()
function visit(u) {
  if (seen.has(u)) return
  seen.add(u)
  for (const v of dl.get(u)) visit(v)
  order.push(u)
}
for (const k of names) visit(k)

const start = new Map()
const finish = new Map()
const depth = new Map()
let total = 0
for (const u of order) {
  let s = 0
  let d = 0
  for (const v of dl.get(u)) {
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
  total = Math.max(total, s + cost.get(u))
}

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((g, i) => { out += `wave ${i}: ${g.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const v of dl.get(k)) rev.get(v).push(k)
  const prio = new Map()
  for (const u of [...order].reverse()) {
    let m = 0
    for (const x of rev.get(u)) m = Math.max(m, prio.get(x))
    prio.set(u, m + cost.get(u))
  }
  const fin = new Map()
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0
  let remaining = names.length
  let makespan = 0
  while (remaining > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of names) {
        if (fin.has(k)) continue
        if (!dl.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best)) best = k
      }
      if (best === null) break
      const f = t + cost.get(best)
      fin.set(best, f)
      freeAt[wi] = f
      runs[wi].push(` ${best}@${t}-${f}`)
      makespan = Math.max(makespan, f)
      remaining--
    }
    if (remaining === 0) break
    t = Math.min(...freeAt.filter((f) => f > t))
  }
  runs.forEach((r, i) => { out += `worker ${i}:${r.join('')}\n` })
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
