/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parseDocument } from './parse.js'
import { renderJson, renderKeys } from './render.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let root
try {
  root = parseDocument(lines)
} catch (e) {
  if (e && e.confError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(args[0] === 'json' ? renderJson(root) : renderKeys(root))
"}

{"file_path":"src/render.js","content":"/** Output of a parsed document as canonical JSON or as a key listing. */

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedEntries = (node) => [...node.m.entries()].sort((p, q) => cmp(p[0], q[0]))

function json(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  if (node.k === 'table') {
    const es = sortedEntries(node)
    if (!es.length) return '{}'
    return '{\n' + es.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${json(v, indent + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (node.k === 'array') {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((v) => pad + json(v, indent + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(node.v)
}

export function renderJson(root) {
  return json(root, 0) + '\n'
}

export function renderKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.k === 'table') {
      for (const [k, v] of sortedEntries(node)) {
        const p = path === null ? k : `${path}.${k}`
        out.push(`${p} ${v.k}`)
        walk(v, p)
      }
    } else if (node.k === 'array') {
      node.items.forEach((v, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${v.k}`)
        walk(v, p)
      })
    }
  }
  walk(root, null)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

{"file_path":"src/parse.js","content":"/** Parser for the configuration document. */

class ConfError extends Error {
  constructor(msg) {
    super(msg)
    this.confError = true
    this.line = 0
  }
}
const fail = (msg) => {
  throw new ConfError(msg)
}

const newTable = () => ({ k: 'table', m: new Map(), hd: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.c)) this.i++
  }
  /** At end of line or at a comment start (after whitespace skipping). */
  atEnd() {
    return this.c === undefined || this.c === '#' || this.c === ';'
  }

  quoted() {
    const q = this.c
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === '"' && c === '\\') {
        const e = this.c
        if (e === undefined) fail('unterminated string')
        this.i++
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else fail(`invalid escape \\${String.fromCodePoint(this.s.codePointAt(this.i - 1))}`)
      } else out += c
    }
  }

  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.quoted()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.c)) this.i++
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = []
    this.ws()
    parts.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
  }

  value(base) {
    this.ws()
    const c = this.c
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { k: 'string', v: this.quoted() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && this.c !== ',' && this.c !== ']' && this.c !== '}') this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true' || tok === 'false') return { k: 'boolean', v: tok === 'true' }
    if (INT.test(tok)) return { k: 'integer', v: Number(tok.replace(/_/g, '')) }
    if (FLOAT.test(tok)) return { k: 'float', v: Number(tok.replace(/_/g, '')) }
    return fail(`invalid value ${tok}`)
  }

  array(base) {
    this.i++
    const items = []
    this.ws()
    if (this.c === ']') {
      this.i++
      return { k: 'array', items, aot: false }
    }
    for (;;) {
      items.push(this.value(base))
      this.ws()
      if (this.c === ',') {
        this.i++
        this.ws()
        if (this.c === ']') {
          this.i++
          break
        }
      } else if (this.c === ']') {
        this.i++
        break
      } else fail('unterminated array')
    }
    return { k: 'array', items, aot: false }
  }

  inline(base) {
    this.i++
    const t = newTable()
    t.hd = true
    this.ws()
    if (this.c === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.c === undefined || this.c === '#' || this.c === ';') fail('unterminated inline table')
      this.pair(t, base)
      this.ws()
      if (this.c === ',') this.i++
      else if (this.c === '}') {
        this.i++
        return t
