{"file_path":"src/render.js","content":"/** Output of a parsed document as canonical JSON or as a key listing. */

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedEntries = (node) => [...node.m.entries()].sort((p, q) => cmp(p[0], q[0]))

function json(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  if (node.k === 'table') {
    const es = sortedEntries(node)
    if (!es.length) return '{}'
    return '{\n' + es.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${json(v, indent + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (node.k === 'array') {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((v) => pad + json(v, indent + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(node.v)
}

export function renderJson(root) {
  return json(root, 0) + '\n'
}

export function renderKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.k === 'table') {
      for (const [k, v] of sortedEntries(node)) {
        const p = path === null ? k : `${path}.${k}`
        out.push(`${p} ${v.k}`)
        walk(v, p)
      }
    } else if (node.k === 'array') {
      node.items.forEach((v, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${v.k}`)
        walk(v, p)
      })
    }
  }
  walk(root, null)
  return out.length ? out.join('\n') + '\n' : ''
}
