        return parts
      }
    }
  }

  value(base) {
    this.ws()
    const c = this.c
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { k: 'string', v: this.quoted() }
